import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix } from 'three/tsl';
import { gsap } from 'gsap';

function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;
  const root = new Group();
  const resources = [];
  const timelines = [];

  const visualSpec = config.intent?.visualSpec ?? {};
  const colors = visualSpec.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const backdropGeometry = new PlaneGeometry(7, 6);
  const backdropMaterial = new MeshBasicNodeMaterial();
  backdropMaterial.colorNode = mix(
    vec3(0.043, 0.043, 0.063),
    vec3(0.086, 0.086, 0.114),
    uv().y
  );

  const backdrop = new Mesh(backdropGeometry, backdropMaterial);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  resources.push(backdropGeometry, backdropMaterial);

  const shadowGeometry = new PlaneGeometry(2.75, 0.82);
  const shadowMaterial = new MeshBasicNodeMaterial({
    color: colors.ink,
    transparent: true,
    opacity: 0.48
  });
  const shadow = new Mesh(shadowGeometry, shadowMaterial);
  shadow.position.set(0, -0.08, -0.08);
  shadow.scale.set(1, 0.34, 1);
  root.add(shadow);
  resources.push(shadowGeometry, shadowMaterial);

  const card = new Group();
  card.position.z = 0.08;
  root.add(card);

  const edgeGeometry = new PlaneGeometry(2.48, 0.76);
  const edgeMaterial = new MeshBasicNodeMaterial({
    color: colors.accent,
    transparent: true,
    opacity: 0.22
  });
  const edgeGlow = new Mesh(edgeGeometry, edgeMaterial);
  edgeGlow.position.z = -0.025;
  card.add(edgeGlow);
  resources.push(edgeGeometry, edgeMaterial);

  const panelGeometry = new PlaneGeometry(2.36, 0.64);
  const panelMaterial = new MeshBasicNodeMaterial({
    color: new Color(colors.paper)
  });
  const panel = new Mesh(panelGeometry, panelMaterial);
  panel.position.z = 0.02;
  card.add(panel);
  resources.push(panelGeometry, panelMaterial);

  const accentGeometry = new PlaneGeometry(2.16, 0.035);
  const accentMaterial = new MeshBasicNodeMaterial({
    color: colors.accent,
    transparent: true,
    opacity: 0.94
  });
  const accentEdge = new Mesh(accentGeometry, accentMaterial);
  accentEdge.position.set(0, -0.285, 0.045);
  card.add(accentEdge);
  resources.push(accentGeometry, accentMaterial);

  const highlightGeometry = new PlaneGeometry(0.22, 0.035);
  const highlightMaterial = new MeshBasicNodeMaterial({
    color: colors.paper,
    transparent: true,
    opacity: 0.55
  });
  const highlight = new Mesh(highlightGeometry, highlightMaterial);
  highlight.position.set(-0.88, 0.285, 0.045);
  card.add(highlight);
  resources.push(highlightGeometry, highlightMaterial);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      if (root.userData.cleaned) return;
      if (ctx.THREE.SRGBColorSpace) texture.colorSpace = ctx.THREE.SRGBColorSpace;
      panelMaterial.map = texture;
      panelMaterial.needsUpdate = true;
    }).catch(() => {});
  }

  let hoverTween = null;
  let pressTimeline = null;
  let focused = false;

  root.userData.handlers = {
    hover(active = true) {
      if (hoverTween) hoverTween.kill();
      hoverTween = gsap.to(card.position, {
        y: active ? 0.15 : 0,
        duration: 0.3,
        ease: 'power3.out'
      });
      timelines.push(hoverTween);
    },

    click() {
      if (pressTimeline) pressTimeline.kill();
      pressTimeline = gsap.timeline();
      pressTimeline
        .to(card.scale, {
          x: 0.97,
          y: 0.97,
          duration: 0.12,
          ease: 'power2.out'
        })
        .to(card.scale, {
          x: 1,
          y: 1,
          duration: 0.42,
          ease: 'back.out(2)'
        });
      timelines.push(pressTimeline);
      ctx.emit('hub-collection.select', { node: config.id ?? 'hub-collection-badge' });
    },

    focus() {
      focused = true;
      gsap.to(edgeMaterial, {
        opacity: 0.82,
        duration: 0.22,
        ease: 'power2.out'
      });
    },

    blur() {
      focused = false;
      gsap.to(edgeMaterial, {
        opacity: 0.22,
        duration: 0.3,
        ease: 'power2.out'
      });
    }
  };

  root.userData.cleanup = () => {
    if (root.userData.cleaned) return;
    root.userData.cleaned = true;

    for (const timeline of timelines) {
      timeline?.kill?.();
    }

    for (const resource of resources) {
      resource?.dispose?.();
    }

    root.traverse((object) => {
      if (object.material && !resources.includes(object.material)) {
        object.material.dispose?.();
      }
    });
  };

  return root;
}

export default createNode;
